properties.query:
let windowSize = 30m;

// S101: Leader Hijack
let S101 =
    UAVSwarmComms_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'leader_hijack'
    | extend Stage = 'S101', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S102: Consensus Poisoning
let S102 =
    UAVSwarmComms_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'consensus_poison'
    | extend Stage = 'S102', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S103: Collision Course
let S103 =
    UAVSwarmComms_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'collision_course'
    | extend Stage = 'S103', SwarmId = tostring(SwarmId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

union S101, S102, S103
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by SwarmId
| where StageCount >= 2
| extend CampaignType = "C23_리더하이재킹_합의포이즈닝_충돌유도"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, SwarmId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
